const students = [
  { name: "민지", score: 80 },
  { name: "준호", score: 65 },
  { name: "서연", score: 92 },
];
let passed = 0;

for (let i = 0; i < students.length; i++) {
  if (students[i].score >= 70) {
    passed++;
  }
}

console.log(passed + "명 합격");

